# The repo's check flow — the deterministic place the whole-repo Claudinite
# world sweep runs at each change. The site is static and has no test suite of
# its own yet; when it gains one, add it as a step ahead of the sweep rather
# than as a separate workflow, so one red flow means one thing.
#
# The WORK scope is deliberately absent here: it judges a session's own change
# with that session's transcript and runs at the Stop hook, not in CI.
name: Checks

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  checks:
    name: Claudinite world sweep
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: '22'

      # The engine's always-vendored Node CLI, invoked as the standalone
      # command — never as a language-specific test file a runner discovers.
      - name: Claudinite world scope
        run: node .claudinite/shared/engine/checks/check_the_world.mjs
=====.github/workflows/claudinite-scheduler.yml=====
# Claudinite per-repo task scheduler — the repo's ONLY cron
# (per-project-scheduling DESIGN §3). A thin shim: all logic lives in the
# vendored engine, so this file changes rarely (schema and behavior changes ride
# the vendor refresh, not edits here). It runs hourly on a repo-hashed minute
# constrained to :10–:50 — spreading the fleet, dodging GitHub's :00 stampede,
# and staying clear of the hour boundary the slot math anchors on.
#
# The minute below is a placeholder; bootstrap/vendoring rewrites it to this
# repo's stable hashed minute in :10–:50, computed by
# `node .claudinite/shared/engine/scheduler/hash-minute.mjs <owner/repo>`
# (scheduler-workflow-shape enforces the range; baselining re-derives the value to
# catch drift). `workflow_dispatch` allows a manual run; the concurrency group
# serializes runs so a slow run and its successor never overlap.
#
# A manual run may carry `overrides` — ONE free-form `KEY=value` string, because
# GitHub cannot declare arbitrary named inputs. It reaches the engine as
# `CLAUDINITE_OVERRIDES`, and the engine understands exactly one key:
# `FORCE_TASKS=<comma-separated task ids>`.
# It runs those tasks even though their slot has already passed, and
# WITHOUT consulting their preconditions — forcing is the operator's decision, so
# nothing asks the task whether it agrees. The engine learns "run these ids",
# never what any of them do, and no task declaration mentions forcing at all.
name: Claudinite scheduler

on:
  schedule:
    - cron: '39 * * * *'
  workflow_dispatch:
    inputs:
      overrides:
        description: 'Manual-run overrides: comma-separated KEY=value. FORCE_TASKS=<task ids> runs those tasks unconditionally, even when their slot has passed, e.g. FORCE_TASKS=baselining.'
        required: false
        default: ''

concurrency:
  group: claudinite-scheduler
  cancel-in-progress: false

permissions:
  contents: write        # read the repo + vendored engine; baselining's deliver() pushes the maintenance branch (task-prework §7/E4)
  issues: write          # file / label / close dispatch issues
  pull-requests: write   # baselining's deliver() opens the per-cycle maintenance PR and arms auto-merge
  actions: write         # read the run ledger (last successful run) for due-slot math, AND
                         # dispatch a workflow a task drives (store-release fires the release
                         # orchestrator's daily leg) — creating a workflow_dispatch event needs
                         # write, not read, and `read` silently 403s the POST

jobs:
  schedule:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Evaluate schedule and dispatch due tasks
        env:
          GITHUB_TOKEN: ${{ github.token }}
          # Empty on every scheduled run — `inputs` is only populated by
          # workflow_dispatch. The engine reads only FORCE_TASKS out of it.
          CLAUDINITE_OVERRIDES: ${{ inputs.overrides }}
        run: node .claudinite/shared/engine/scheduler/run.mjs

  # A scheduled run reaches no one when it goes red, so escalate a whole-run
  # failure to a human-visible `workflow-failure` issue (DESIGN §3.6,
  # gha/scheduled-failure-escalation). Converges to ONE open issue by a fixed
  # title (create-or-comment), and ensures the label first since a first-run
  # failure may precede the scheduler's own label-ensure.
  report-failure:
    needs: schedule
    if: failure()
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
      - uses: actions/github-script@v7
        with:
          script: |
            const { owner, repo } = context.repo;
            const title = 'Claudinite scheduler run failed';
            await github.rest.issues.createLabel({ owner, repo, name: 'workflow-failure', color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' }).catch(() => {});
            const run = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;
            const body = `The Claudinite scheduler run failed: ${run}`;
            const found = await github.rest.search.issuesAndPullRequests({ q: `repo:${owner}/${repo} is:issue is:open in:title "${title}"` });
            if (found.data.total_count > 0) await github.rest.issues.createComment({ owner, repo, issue_number: found.data.items[0].number, body });
            else await github.rest.issues.create({ owner, repo, title, labels: ['workflow-failure'], body });
=====.github/workflows/deploy-pages.yml=====
# Releases the site to GitHub Pages on every push to main. The site is static
# and hand-authored, so there is no build step: the site/ directory is the
# artifact, uploaded as-is. Publishing only site/ (never the repo root) keeps
# the agent tooling and research trees out of the published site.
name: Deploy to GitHub Pages

on:
  push:
    branches: [main]
  workflow_dispatch:

permissions:
  # write: the release commits its version bump back to main
  contents: write
  pages: write
  id-token: write

# One deploy at a time; let an in-flight production deploy finish.
concurrency:
  group: pages
  cancel-in-progress: false

jobs:
  deploy:
    name: Deploy site/
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - uses: actions/checkout@v4

      # Every production release advances the version. package.json is the single
      # source of truth; the bumped file is committed back to main so the number
      # in the repo always names the last release that actually went out.
      - name: Bump version
        id: bump
        run: |
          NEW_VERSION=$(node scripts/bump-version.mjs)
          echo "version=$NEW_VERSION" >> "$GITHUB_OUTPUT"
          echo "Released version $NEW_VERSION"

      - name: Commit the version bump
        # [skip ci] keeps this commit from re-triggering this workflow, so there
        # is no deploy loop. Rebase-and-retry because the Claudinite scheduler and
        # its maintenance PRs also land on main, and a race here would otherwise
        # lose the bump and leave the repo claiming an older version than shipped.
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add package.json
          git commit -m "Bump version to ${{ steps.bump.outputs.version }} [skip ci]"
          for attempt in 1 2 3 4 5; do
            if git push origin HEAD:main; then
              echo "Pushed the version bump on attempt $attempt."
              break
            fi
            if [ "$attempt" = "5" ]; then
              echo "Failed to push the version bump after $attempt attempts." >&2
              exit 1
            fi
            echo "Push rejected — rebasing on latest main and retrying (attempt $attempt)."
            git pull --rebase origin main
          done

      - name: Inject Cloudflare Web Analytics token
        # The beacon token is public (it ships in the client), so it lives in a
        # repo *variable*, not a secret. When set, substitute it into the served
        # analytics.js; when unset, the placeholder stays and analytics no-ops.
        # sed uses '#' as its delimiter so the line contains no shell pipe.
        env:
          CLOUDFLARE_ANALYTICS_TOKEN: ${{ vars.CLOUDFLARE_ANALYTICS_TOKEN }}
        run: |
          if [ -n "$CLOUDFLARE_ANALYTICS_TOKEN" ]; then
            sed -i "s#REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN#${CLOUDFLARE_ANALYTICS_TOKEN}#" site/analytics.js
            echo "Injected Cloudflare Web Analytics token from the CLOUDFLARE_ANALYTICS_TOKEN variable."
          else
            echo "CLOUDFLARE_ANALYTICS_TOKEN variable not set — analytics stays off (placeholder retained)."
          fi

      - uses: actions/configure-pages@v5

      - uses: actions/upload-pages-artifact@v3
        with:
          path: site

      - id: deployment
        uses: actions/deploy-pages@v4
=====scripts/bump-version.mjs=====
#!/usr/bin/env node
//
// Bump the site version for a production release.
//
// Scheme: 1.<mmdd>.<previous patch + 1>
//   - major  stays 1
//   - minor  is the release date as zero-padded month+day (Asia/Jerusalem, the
//            timezone the rest of the fleet stamps its builds in)
//   - patch  is a monotonic counter: previous patch + 1, so it always advances
//            even when the day (and therefore the minor) rolls over
//
// package.json is the single source of truth for the version. The deploy
// workflow runs this, then commits the bumped file back to main — so the number
// in the repo always names the last release that actually went out.
//
// Prints the new version to stdout (nothing else) so the workflow can capture it.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const pkgPath = join(dirname(fileURLToPath(import.meta.url)), "..", "package.json");
const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));

// The current patch is the third dotted component; treat anything unparseable
// (e.g. the initial "1.0.0") as 0 so the first bump lands on patch 1.
const prevPatch = Number.parseInt(String(pkg.version ?? "").split(".")[2], 10);
const newPatch = (Number.isFinite(prevPatch) ? prevPatch : 0) + 1;

const parts = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Jerusalem", month: "2-digit", day: "2-digit",
}).formatToParts(new Date());
const mm = parts.find((p) => p.type === "month").value;
const dd = parts.find((p) => p.type === "day").value;

const newVersion = `1.${mm}${dd}.${newPatch}`;
pkg.version = newVersion;
writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n");

console.log(newVersion);
=====site/analytics.js=====
// Cloudflare Web Analytics — privacy-first, cookieless visitor counts.
//
// Cloudflare Web Analytics sets no cookies, stores no personal data, and can't
// track visitors across sites, so it needs no consent banner (see privacy.html).
//
// The beacon token is NOT a secret — it ships in the client and is visible to
// every visitor — so it lives in a GitHub Actions *variable* (not a secret):
//   repo Settings -> Secrets and variables -> Actions -> Variables ->
//   CLOUDFLARE_ANALYTICS_TOKEN
// The Pages deploy (.github/workflows/deploy-pages.yml) injects that value into
// the placeholder below at build time.
//
// TO ENABLE: create a free site in the Cloudflare dashboard (Web Analytics ->
// "Add a site"), then add its token as the CLOUDFLARE_ANALYTICS_TOKEN repo variable.
// It works on GitHub Pages as-is — no hosting or DNS move to Cloudflare needed.
//
// Until a real token is injected (variable unset, or running locally), this
// loader does nothing: no beacon is requested, so the site keeps its "no
// analytics" behaviour and never ships a broken tag.
(function () {
  var TOKEN = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';
  // Bail out while the placeholder is still in place (startsWith, ES5-safe).
  if (!TOKEN || TOKEN.lastIndexOf('REPLACE_WITH', 0) === 0) return;

  var beacon = document.createElement('script');
  beacon.defer = true;
  beacon.src = 'https://static.cloudflareinsights.com/beacon.min.js';
  beacon.setAttribute('data-cf-beacon', JSON.stringify({ token: TOKEN }));
  (document.head || document.documentElement).appendChild(beacon);
})();

